import{_ as e,o as a,c as r,a5 as i}from"./chunks/framework.DJo0M80U.js";const c=JSON.parse('{"title":"HJ25 数据分类处理","description":"较难 通过率：23.51% 时间限制：1秒 空间限制：32M 知识点 排序 模拟 哈希 描述 信息社会，有海量的数据需要分析处理，比如公安局分析身份证号码、 QQ 用户、手机号码、银行帐号等信息及活动记录。 采集输入大数据和分类规则，通过大数据分类处理程序，将大数据分类输出。 数。","frontmatter":{"title":"HJ25 数据分类处理","date":"2026-08-11T00:00:00.000Z","categories":["前端面试与实战"],"tags":["前端面试","算法","求职","教程","OneNote","算法训练"],"description":"较难 通过率：23.51% 时间限制：1秒 空间限制：32M 知识点 排序 模拟 哈希 描述 信息社会，有海量的数据需要分析处理，比如公安局分析身份证号码、 QQ 用户、手机号码、银行帐号等信息及活动记录。 采集输入大数据和分类规则，通过大数据分类处理程序，将大数据分类输出。 数。","sidebarWeight":87,"lastUpdated":false,"feed":false,"source":"onenote","sourceNote":"OneNote/a-吊打面试官/算法题/华为较难题/HJ25 数据分类处理.md"},"headers":[],"relativePath":"posts/前端面试与实战/03-算法训练/华为较难题/HJ25 数据分类处理.md","filePath":"posts/前端面试与实战/03-算法训练/华为较难题/HJ25 数据分类处理.md"}'),o={name:"posts/前端面试与实战/03-算法训练/华为较难题/HJ25 数据分类处理.md"};function s(n,t,l,h,m,d){return a(),r("div",null,[...t[0]||(t[0]=[i('<div><h1 id="hj25-数据分类处理" tabindex="-1">HJ25 数据分类处理 <a class="header-anchor" href="#hj25-数据分类处理" aria-label="Permalink to &quot;HJ25 数据分类处理&quot;">​</a></h1><blockquote><p>本节目标：理解“HJ25 数据分类处理”的核心思路，并能把它用于实际开发或面试表达。 较难 通过率：23.51% 时间限制：1秒 空间限制：32M 知识点==排序====模拟====哈希== <strong>描述</strong> 信息社会，有海量的数据需要分析处理，比如公安局分析身份证号码、 QQ 用户、手机号码、银行帐号等信息及活动记录。 采集输入大数据和分类规则，通过大数据分类处理程序，将大数据分类输出。</p></blockquote><p>数据范围：1≤<em>I</em>,<em>R</em>≤100 ，输入的整数大小满足 0≤<em>val</em>≤(2^31)-1 <strong>输入描述：</strong> 一组输入整数序列I和一组规则整数序列R，I和R序列的第一个整数为序列的个数（个数不包含第一个整数）；整数范围为0~(2^31)-1，序列个数不限 <strong>输出描述：</strong> 从R依次中取出R&lt;i&gt;，对I进行处理，找到满足条件的I： I整数对应的数字需要连续包含R&lt;i&gt;对应的数字。比如R&lt;i&gt;为23，I为231，那么I包含了R&lt;i&gt;，条件满足 。 按R&lt;i&gt;从小到大的顺序: (1)先输出R&lt;i&gt;； (2)再输出满足条件的I的个数； (3)然后输出满足条件的I在I序列中的位置索引(从0开始)； (4)最后再输出I。 附加条件： (1)R&lt;i&gt;需要从小到大排序。相同的R&lt;i&gt;只需要输出索引小的以及满足条件的I，索引大的需要过滤掉 (2)如果没有满足条件的I，对应的R&lt;i&gt;不用输出 (3)最后需要在输出序列的第一个整数位置记录后续整数序列的个数(不包含“个数”本身)</p><p>序列I：15,123,456,786,453,46,7,5,3,665,453456,745,456,786,453,123（第一个15表明后续有15个整数） 序列R：5,6,3,6,3,0（第一个5表明后续有5个整数） 输出：<em>30</em>_,_ <em>3</em>_,6,0,123_,3,453,7,3,9,453456,13,453,14,123,6,7,1,456,2,786,4,46,8,665,9,453456,11,456,12,786 说明： <em>30</em>----后续有30个整数 <em>3</em>----从小到大排序，第一个R&lt;i&gt;为0，但没有满足条件的I，不输出0，而下一个R&lt;i&gt;是3 <em>6---</em> <em>存在6个包含3的I</em><em>0---</em> <em>123所在的原序号为0</em><em>123---</em> <em>123包含3，满足条件</em><strong>示例1</strong> 输入： 15 123 456 786 453 46 7 5 3 665 453456 745 456 786 453 1235 6 3 6 3 0 ==复制== 输出： 30 3 6 0 123 3 453 7 3 9 453456 13 453 14 123 6 7 1 456 2 786 4 46 8 665 9 453456 11 456 12 786 ==复制== 说明： 将序列R：5,6,3,6,3,0（第一个5表明后续有5个整数）排序去重后，可得0,3,6。序列I没有包含0的元素。序列I中包含3的元素有：I[0]的值为123、I[3]的值为453、I[7]的值为3、I[9]的值为453456、I[13]的值为453、I[14]的值为123。序列I中包含6的元素有：I[1]的值为456、I[2]的值为786、I[4]的值为46、I[8]的值为665、I[9]的值为453456、I[11]的值为456、I[12]的值为786。最后按题目要求的格式进行输出即可。</p><h1 id="读取输入的i序列和r序列-去掉序列的第一个整数-即个数" tabindex="-1">读取输入的I序列和R序列，去掉序列的第一个整数（即个数） <a class="header-anchor" href="#读取输入的i序列和r序列-去掉序列的第一个整数-即个数" aria-label="Permalink to &quot;读取输入的I序列和R序列，去掉序列的第一个整数（即个数）&quot;">​</a></h1><p>iList = input().split()[1:] rList = list(map(int, input().split()[1:]))</p><h1 id="对规则序列r进行去重并排序-确保每个规则只处理一次" tabindex="-1">对规则序列R进行去重并排序，确保每个规则只处理一次 <a class="header-anchor" href="#对规则序列r进行去重并排序-确保每个规则只处理一次" aria-label="Permalink to &quot;对规则序列R进行去重并排序，确保每个规则只处理一次&quot;">​</a></h1><p>sortedUniqueRList = sorted(set(rList))</p><h1 id="准备一个列表来收集最终的输出结果" tabindex="-1">准备一个列表来收集最终的输出结果 <a class="header-anchor" href="#准备一个列表来收集最终的输出结果" aria-label="Permalink to &quot;准备一个列表来收集最终的输出结果&quot;">​</a></h1><p>finalResults = []</p><h1 id="遍历每个唯一且已排序的规则" tabindex="-1">遍历每个唯一且已排序的规则 <a class="header-anchor" href="#遍历每个唯一且已排序的规则" aria-label="Permalink to &quot;遍历每个唯一且已排序的规则&quot;">​</a></h1><p>for r in sortedUniqueRList: rStr = str(r) # 将规则转换成字符串，以便后续查找匹配</p><h1 id="用于存储当前规则匹配到的i元素的索引和元素值" tabindex="-1">用于存储当前规则匹配到的I元素的索引和元素值 <a class="header-anchor" href="#用于存储当前规则匹配到的i元素的索引和元素值" aria-label="Permalink to &quot;用于存储当前规则匹配到的I元素的索引和元素值&quot;">​</a></h1><p>matchedIs = []</p><h1 id="遍历i序列-查找包含当前规则字符串的元素" tabindex="-1">遍历I序列，查找包含当前规则字符串的元素 <a class="header-anchor" href="#遍历i序列-查找包含当前规则字符串的元素" aria-label="Permalink to &quot;遍历I序列，查找包含当前规则字符串的元素&quot;">​</a></h1><p>for idx, i in enumerate(iList): if rStr in i: # 如果I元素包含当前规则字符串 matchedIs.append((idx, i)) # 记录匹配的索引和元素值</p><h1 id="如果当前规则有匹配到的i元素" tabindex="-1">如果当前规则有匹配到的I元素 <a class="header-anchor" href="#如果当前规则有匹配到的i元素" aria-label="Permalink to &quot;如果当前规则有匹配到的I元素&quot;">​</a></h1><p>if matchedIs:</p><h1 id="将规则值、匹配到的i元素个数、每个匹配元素的索引和值添加到结果中" tabindex="-1">将规则值、匹配到的I元素个数、每个匹配元素的索引和值添加到结果中 <a class="header-anchor" href="#将规则值、匹配到的i元素个数、每个匹配元素的索引和值添加到结果中" aria-label="Permalink to &quot;将规则值、匹配到的I元素个数、每个匹配元素的索引和值添加到结果中&quot;">​</a></h1><p>finalResults.extend([r] + [len(matchedIs)] + [item for match in matchedIs for item in match])</p><h1 id="在结果序列的开头添加后续整数序列的个数" tabindex="-1">在结果序列的开头添加后续整数序列的个数 <a class="header-anchor" href="#在结果序列的开头添加后续整数序列的个数" aria-label="Permalink to &quot;在结果序列的开头添加后续整数序列的个数&quot;">​</a></h1><p>finalResults.insert(0, len(finalResults))</p><h1 id="将结果序列中的整数转换成字符串-并用空格连接成最终的输出字符串" tabindex="-1">将结果序列中的整数转换成字符串，并用空格连接成最终的输出字符串 <a class="header-anchor" href="#将结果序列中的整数转换成字符串-并用空格连接成最终的输出字符串" aria-label="Permalink to &quot;将结果序列中的整数转换成字符串，并用空格连接成最终的输出字符串&quot;">​</a></h1><p>output = &#39; &#39;.join(map(str, finalResults)) print(output)</p><p><strong>[<strong><strong>item</strong> <strong>for</strong> <strong>match</strong> <strong>in</strong> <strong>matchedIs</strong> <strong>for</strong> <strong>item</strong> <strong>in</strong> <strong>match</strong></strong>])</strong> 这里，matchedIs是一个列表，其中的每个元素match是一个元组。这个元组包含了两个部分：一个是I序列中满足条件的元素的索引，另一个是该元素的值。例如，如果一个满足条件的元素在I序列的第0位置，且其值为123，那么对应的元组就是(0, &#39;123&#39;)。</p><p>for match in matchedIs: 这个循环遍历matchedIs列表中的每个元素，每次循环中的match就是列表中的一个元组。</p><p>for item in match: 这个循环遍历上面提到的match元组中的每个项。第一次循环得到的是索引（例如0），第二次循环得到的是值（例如&#39;123&#39;）。所以，这里的item首先是元组中的第一个元素（索引），接着是第二个元素（值）。</p><p>因此，这个列表推导式最终会生成一个新列表，这个列表包含了所有匹配元素的索引和值，且这些索引和值是交替出现的。比如，如果matchedIs包含了两个元组(0, &#39;123&#39;)和(1, &#39;456&#39;)，那么通过这个列表推导式得到的新列表就是[0, &#39;123&#39;, 1, &#39;456&#39;]。</p><p>在这个上下文中，“返回”的含义是列表推导式在遍历过程中构造并最终生成一个新的列表。这个新列表中的元素item是从原始数据结构（这里是matchedIs列表中的元组）逐个提取出来的。</p></div>',1)])])}const I=e(o,[["render",s]]);export{c as __pageData,I as default};
